/** Builds the real page a search hit should open, scoped to the org's slug. */
async function hrefFor(
  orgId: OrgId,
  orgSlug: string,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  switch (kind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
      return issue ? await issueHref(orgId, orgSlug, issue) : `/${orgSlug}`;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      if (!comment) return `/${orgSlug}`;
      const issue = await issueRepo.findIssueById(orgId, comment.issueId);
      return issue ? await issueHref(orgId, orgSlug, issue) : `/${orgSlug}`;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as Project["id"],
      );
      return project ? `/${orgSlug}/projects/${project.slug}` : `/${orgSlug}`;
    }
  }
}

async function issueHref(
  orgId: OrgId,
  orgSlug: string,
  issue: Issue,
): Promise<string> {
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return `/${orgSlug}`;
  return `/${orgSlug}/projects/${project.slug}/issues/${issue.number}`;
}

